package com.fream.back.global.config.security;

import com.fream.back.domain.user.redis.AuthRedisService;
import com.fream.back.domain.user.repository.UserRepository;
import com.fream.back.domain.user.service.command.AuthService;
import com.fream.back.domain.user.security.oauth2.CustomOAuth2UserService;
import com.fream.back.domain.user.security.oauth2.OAuth2AuthenticationSuccessHandler;
import com.fream.back.global.config.security.filter.LoginAuthenticationFilter;
import com.fream.back.global.config.security.filter.LogoutAuthenticationFilter;
import com.fream.back.global.config.security.filter.TokenRefreshFilter;
import com.fream.back.global.security.redis.IpBlockingRedisService;
import com.fream.back.global.security.filter.IpBlockingFilter;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
public class SecurityConfig {
    private final JwtTokenProvider jwtTokenProvider;
    private final AuthRedisService authRedisService;
    private final IpBlockingRedisService ipBlockingRedisService;
    private final CustomOAuth2UserService customOAuth2UserService;
    private final OAuth2AuthenticationSuccessHandler oAuth2AuthenticationSuccessHandler;
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final AuthService authService;

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        // 커스텀 필터들 생성
        IpBlockingFilter ipBlockingFilter = new IpBlockingFilter(ipBlockingRedisService);
        JwtAuthenticationFilter jwtFilter = new JwtAuthenticationFilter(jwtTokenProvider, authRedisService);
        LoginAuthenticationFilter loginFilter = new LoginAuthenticationFilter(authService);
        LogoutAuthenticationFilter logoutFilter = new LogoutAuthenticationFilter(
                authRedisService, jwtTokenProvider);
        TokenRefreshFilter refreshFilter = new TokenRefreshFilter(
                jwtTokenProvider, authRedisService, userRepository);

        http
                // 1) 요청 권한 설정
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(whiteListPaths()).permitAll()
                        .anyRequest().authenticated())

                // 2) CSRF 비활성화 (REST API의 경우)
                .csrf(csrf -> csrf.disable())

                // 3) 폼 로그인 비활성화
                .formLogin(form -> form.disable())

                // 4) HTTP 기본 인증 비활성화 (Basic Auth 비활성화)
                .httpBasic(httpBasic -> httpBasic.disable())

                // 5) 세션을 사용하지 않도록 설정 (STATELESS)
                .sessionManagement(session -> session.disable())

                // OAuth2 로그인 설정
                .oauth2Login(oauth2 -> oauth2
                        .authorizationEndpoint(endpoint -> endpoint
                                .baseUri("/oauth2/authorization"))
                        .redirectionEndpoint(endpoint -> endpoint
                                .baseUri("/login/oauth2/code/*"))
                        .userInfoEndpoint(endpoint -> endpoint
                                .userService(customOAuth2UserService))
                        .successHandler(oAuth2AuthenticationSuccessHandler))

                // 커스텀 필터들 추가 (순서 중요!)
                .addFilterBefore(ipBlockingFilter, UsernamePasswordAuthenticationFilter.class)
                .addFilterAfter(loginFilter, IpBlockingFilter.class)
                .addFilterAfter(logoutFilter, LoginAuthenticationFilter.class)
                .addFilterAfter(refreshFilter, LogoutAuthenticationFilter.class)
                .addFilterAfter(jwtFilter, TokenRefreshFilter.class);

        return http.build();
    }

    /**
     * [Whitelist] - 인증 없이 접근 가능한 경로들
     */
    private String[] whiteListPaths() {
        return new String[] {
                // 정적 리소스
                "/favicon.ico",
                "/error",

                // OAuth 관련
                "/oauth2/**",
                "/login/oauth2/**",
                "/oauth/**",

                // 인증 관련 (필터에서 처리됨)
                "/auth/login",          // 로그인 (LoginAuthenticationFilter에서 처리)
                "/auth/logout",         // 로그아웃 (LogoutAuthenticationFilter에서 처리)
                "/auth/refresh",        // 토큰 갱신 (TokenRefreshFilter에서 처리)

                // 공개 API
                "/users/register",              // 회원가입
                "/users/find-email",            // 이메일 찾기
                "/users/reset-password",        // 비밀번호 찾기 - 사용자 확인
                "/users/reset-password-sandEmail", // 비밀번호 찾기 - 이메일 발송
                "/users/reset",                 // 비밀번호 변경
                "/users/verify-identity",       // 본인인증 검증
                "/identity-verification/**",    // 본인인증 관련

                // 관리자 인증 (별도 처리 필요시)
                "/admin/auth/**",

                // 헬스체크 및 모니터링
                "/health",
                "/actuator/**",

                // WebSocket (필요시)
                "/ws/**",

                // 개발/테스트용 (운영환경에서는 제거)
                "/swagger-ui/**",
                "/v3/api-docs/**"
        };
    }

    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
        return config.getAuthenticationManager();
    }
}package com.fream.back.global.config.security;

import com.fream.back.domain.user.entity.Gender;
import com.fream.back.domain.user.redis.AuthRedisService;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.RequiredArgsConstructor;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

/**
 * 매 요청 시 "ACCESS_TOKEN" 쿠키에서 토큰 추출 -> 검증 -> SecurityContextHolder 세팅
 */
@RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtTokenProvider jwtTokenProvider;
    private final AuthRedisService authRedisService;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain)
            throws ServletException, IOException
    {
        // 1) 쿠키에서 AccessToken 찾기
        String accessToken = getCookieValue(request, "ACCESS_TOKEN");

        // 2) 유효성 검증
        if (accessToken != null && jwtTokenProvider.validateToken(accessToken)) {
            // 3) Redis에 존재하는지(화이트리스트)
            if (authRedisService.isAccessTokenValid(accessToken)) {
                // 4) 토큰에서 이메일, 나이, 성별 등
                String email = jwtTokenProvider.getEmailFromToken(accessToken);
                Integer age = authRedisService.getAgeByAccessToken(accessToken);
                Gender gender = authRedisService.getGenderByAccessToken(accessToken);

                // 예) 권한을 넣고 싶다면 GrantedAuthority 생성
                UsernamePasswordAuthenticationToken authentication =
                        new UsernamePasswordAuthenticationToken(email, null, null);

                // 나이/성별 등 추가 정보를 details에 저장
                UserInfo userInfo = new UserInfo(age, gender);
                authentication.setDetails(userInfo);

                SecurityContextHolder.getContext().setAuthentication(authentication);
            } else {
                SecurityContextHolder.clearContext();
            }
        } else {
            SecurityContextHolder.clearContext();
        }

        // 다음 필터로 진행
        filterChain.doFilter(request, response);
    }

    /**
     * 쿠키에서 특정 이름의 값 추출
     */
    private String getCookieValue(HttpServletRequest request, String cookieName) {
        if (request.getCookies() != null) {
            for (Cookie c : request.getCookies()) {
                if (c.getName().equals(cookieName)) {
                    return c.getValue();
                }
            }
        }
        return null;
    }

    /**
     * 임의의 사용자 정보 객체 (SecurityContextHolder에 details로 담을 수 있음)
     */
    public static class UserInfo {
        private final Integer age;
        private final Gender gender;

        public UserInfo(Integer age, Gender gender) {
            this.age = age;
            this.gender = gender;
        }

        public Integer getAge() { return age; }
        public Gender getGender() { return gender; }
    }
}
package com.fream.back.global.config.security;

import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.exceptions.JWTCreationException;
import com.auth0.jwt.exceptions.JWTVerificationException;
import com.auth0.jwt.exceptions.TokenExpiredException;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.fream.back.domain.user.entity.Gender;
import com.fream.back.domain.user.entity.Role;
import com.fream.back.domain.user.redis.AuthRedisService;
import com.fream.back.global.config.security.dto.TokenDto;
import com.fream.back.global.exception.security.ExpiredTokenException;
import com.fream.back.global.exception.security.InvalidTokenException;
import com.fream.back.global.exception.security.TokenCreationException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.util.Date;

/**
 * JWT 생성, 검증을 담당하는 컴포넌트
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class JwtTokenProvider {

    @Value("${jwt.secret}")
    private String secretKey;  // JWT 서명 비밀키

    @Value("${jwt.expiration}")
    private long accessTokenValidityMs; // AccessToken 만료(밀리초)

    @Value("${jwt.refreshExpiration}")
    private long refreshTokenValidityMs; // RefreshToken 만료(밀리초)

    private final AuthRedisService authRedisService;

    /**
     * AccessToken + RefreshToken 동시 발급
     * role 등 추가 클레임을 담으려면 withClaim("role", role) 형태로도 가능
     *
     * @param email 사용자 이메일
     * @param age 사용자 나이
     * @param gender 사용자 성별
     * @param ip 요청 IP 주소
     * @return 액세스 토큰과 리프레시 토큰을 포함한 DTO
     * @throws RuntimeException 토큰 생성 중 오류 발생 시
     */
    public TokenDto generateTokenPair(String email, Integer age, Gender gender, String ip, Role role) {
        log.info("토큰 생성 시작: 이메일={}, 나이={}, 성별={}, IP={}, 권한={}", email, age, gender, ip, role);

        try {
            long now = System.currentTimeMillis();

            // Access Token 생성 (role 정보 추가)
            Date accessExpiry = new Date(now + accessTokenValidityMs);
            String accessToken = JWT.create()
                    .withSubject(email)
                    .withIssuedAt(new Date())
                    .withExpiresAt(accessExpiry)
                    .withClaim("role", role.name()) // 권한 정보 추가
                    .sign(Algorithm.HMAC512(secretKey));

            // Refresh Token 생성
            Date refreshExpiry = new Date(now + refreshTokenValidityMs);
            String refreshToken = JWT.create()
                    .withSubject(email)
                    .withIssuedAt(new Date())
                    .withExpiresAt(refreshExpiry)
                    .sign(Algorithm.HMAC512(secretKey));

            // Redis에 저장 (role 정보도 함께 저장)
            authRedisService.addAccessToken(accessToken, email, age, gender, accessTokenValidityMs, ip, role);
            authRedisService.addRefreshToken(refreshToken, email, refreshTokenValidityMs);

            log.info("토큰 생성 완료: 이메일={}, 액세스 토큰 만료={}, 리프레시 토큰 만료={}",
                    email, accessExpiry, refreshExpiry);

            return new TokenDto(accessToken, refreshToken);
        } catch (JWTCreationException e) {
            log.error("토큰 생성 실패: 이메일={}, 오류={}", email, e.getMessage(), e);
            throw new TokenCreationException(e);
        }
    }

    // role 정보 추출 메서드 추가
    public Role getRoleFromToken(String token) {
        try {
            DecodedJWT decoded = JWT.require(Algorithm.HMAC512(secretKey))
                    .build()
                    .verify(token);
            String roleName = decoded.getClaim("role").asString();
            log.debug("토큰에서 권한 추출: {}", roleName);
            return Role.valueOf(roleName);
        } catch (Exception e) {
            log.error("토큰에서 권한 추출 중 오류: {}", e.getMessage(), e);
            throw new InvalidTokenException("토큰에서 권한을 추출하는 중 오류가 발생했습니다.");
        }
    }

    /**
     * JWT 서명 + 만료시간 검증
     *
     * @param token 검증할 JWT 토큰
     * @return 유효한 토큰인 경우 true
     * @throws ExpiredTokenException 토큰이 만료된 경우
     * @throws InvalidTokenException 토큰이 유효하지 않은 경우
     */
    public boolean validateToken(String token) {
        try {
            JWT.require(Algorithm.HMAC512(secretKey))
                    .build()
                    .verify(token);
            log.debug("토큰 검증 성공");
            return true;
        } catch (TokenExpiredException e) {
            log.warn("만료된 토큰: {}", e.getMessage());
            throw new ExpiredTokenException();
        } catch (JWTVerificationException e) {
            log.warn("유효하지 않은 토큰: {}", e.getMessage());
            throw new InvalidTokenException();
        } catch (Exception e) {
            log.error("토큰 검증 중 예상치 못한 오류: {}", e.getMessage(), e);
            throw new InvalidTokenException("토큰 검증 중 오류가 발생했습니다.");
        }
    }

    /**
     * 토큰에서 subject(email) 추출
     *
     * @param token 이메일을 추출할 JWT 토큰
     * @return 토큰에서 추출한 이메일
     * @throws ExpiredTokenException 토큰이 만료된 경우
     * @throws InvalidTokenException 토큰이 유효하지 않은 경우
     */
    public String getEmailFromToken(String token) {
        try {
            DecodedJWT decoded = JWT.require(Algorithm.HMAC512(secretKey))
                    .build()
                    .verify(token);
            String email = decoded.getSubject();
            log.debug("토큰에서 이메일 추출: {}", email);
            return email;
        } catch (TokenExpiredException e) {
            log.warn("만료된 토큰에서 이메일 추출 시도: {}", e.getMessage());
            throw new ExpiredTokenException();
        } catch (JWTVerificationException e) {
            log.warn("유효하지 않은 토큰에서 이메일 추출 시도: {}", e.getMessage());
            throw new InvalidTokenException();
        } catch (Exception e) {
            log.error("토큰에서 이메일 추출 중 예상치 못한 오류: {}", e.getMessage(), e);
            throw new InvalidTokenException("토큰에서 이메일을 추출하는 중 오류가 발생했습니다.");
        }
    }
