    /**
     * RangeQuery 빌더: min / max 인자를 받아 RangeQuery 만들기
     * 안전한 처리와 로깅 강화
     */
    private Query rangeQuery(String field, Integer gte, Integer lte) {
        if (field == null || field.isBlank()) {
            log.warn("범위 쿼리 생성 시 필드명이 비어있음");
            field = "minPrice";
        }

        final String finalField = field;

        return new Query.Builder()
                .range(r -> {
                    var b = r.field(finalField);
                    if (gte != null) {
                        b.gte(JsonData.of(gte));
                    }
                    if (lte != null) {
                        b.lte(JsonData.of(lte));
                    }
                    return b;
                })
                .build();
    }

    /**
     * 성별 키워드를 정규화하여 변환
     * 안전한 변환과 로깅 강화
     */
    private String convertGender(String genderKeyword) {
        if (genderKeyword == null || genderKeyword.isBlank()) {
            return "UNISEX";
        }

        String normalizedKeyword = genderKeyword.trim().toUpperCase();
        String result;

        switch (normalizedKeyword) {
            case "남자":
            case "남성":
            case "MEN":
            case "MAN":
            case "MALE":
                result = "MALE";
                break;
            case "여자":
            case "여성":
            case "WOMEN":
            case "WOMAN":
            case "FEMALE":
                result = "FEMALE";
                break;
            case "어린이":
            case "아동":
            case "키즈":
            case "KIDS":
            case "KID":
            case "CHILD":
            case "CHILDREN":
                result = "KIDS";
                break;
            case "공용":
            case "유니섹스":
            case "UNISEX":
            case "BOTH":
            case "ALL":
                result = "UNISEX";
                break;
            default:
                result = "UNISEX";
        }

        return result;
    }

