package com.fream.back.domain.order.service.command;


@Service
@RequiredArgsConstructor
@Slf4j
public class OrderBidCommandService {

    private final OrderBidRepository orderBidRepository;
    private final OrderCommandService orderCommandService;
    private final ProductSizeQueryService productSizeQueryService;
    private final UserQueryService userQueryService;
    private final SaleBidQueryService saleBidQueryService;

    @Transactional
    public OrderBid createOrderBid(String email, Long productSizeId, int bidPrice) {
        try {
            // 1. 입력값 검증
            validateCreateOrderBidInput(email, productSizeId, bidPrice);

            // 2. User 조회
            User user = userQueryService.findByEmail(email);

            // 3. ProductSize 조회
            ProductSize productSize = productSizeQueryService.findById(productSizeId)
                    .orElseThrow(() -> new ProductSizeNotFoundException("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));

            // 4. Order 생성
            Order order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);

            // 5. OrderBid 생성 및 저장
            OrderBid orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "주문 입찰 생성");
            return null; // 실행되지 않음 (예외가 던져짐)
        }
    }

    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
        if (email == null || email.trim().isEmpty()) {
            throw new OrderBidAccessDeniedException("사용자 이메일이 없습니다.");
        }
        if (productSizeId == null) {
            throw new ProductSizeNotFoundException("상품 사이즈 ID가 없습니다.");
        }
        if (bidPrice <= 0) {
            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
        }
    }

    private OrderBid createAndSaveOrderBid(User user, ProductSize productSize, int bidPrice, Order order) {
        OrderBid orderBid = OrderBid.builder()
                .user(user)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .order(order)
                .build();

        // 양방향 관계 설정
        orderBid.assignOrder(order);

        return orderBidRepository.save(orderBid);
    }

    @Transactional
    public OrderBid createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
                                          boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
        try {
            // 1. 입력값 검증
            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);

            // 2. 유저 조회
            User buyer = userQueryService.findByEmail(buyerEmail);

            // 3. SaleBid 및 Sale 조회
            SaleBid saleBid = getSaleBidAndValidate(saleBidId);
            Sale sale = saleBid.getSale();

            // 4. Order 생성
            Order order = orderCommandService.createInstantOrder(
                    buyer,
                    saleBid,
                    addressId,
                    isWarehouseStorage,
                    paymentRequest
            );

            // 5. OrderBid 생성 및 저장
            OrderBid orderBid = createInstantOrderBid(order, saleBid, sale);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
            return null; // 실행되지 않음 (예외가 던져짐)
        }
    }

    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, PaymentRequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new OrderBidAccessDeniedException("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new SaleBidNotFoundException("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new InvalidOrderBidDataException("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
        }
    }

    private SaleBid getSaleBidAndValidate(Long saleBidId) {
        SaleBid saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new SaleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Sale sale = saleBid.getSale();
        if (sale == null) {
            throw new InvalidOrderBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }

    private OrderBid createInstantOrderBid(Order order, SaleBid saleBid, Sale sale) {
        ProductSize productSize = saleBid.getProductSize();

        OrderBid orderBid = OrderBid.builder()
                .user(order.getUser()) // 구매자
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(BidStatus.MATCHED) // 즉시 구매는 바로 매칭 상태
                .order(order) // Order와 매핑
                .sale(sale) // 셀러 정보 추가
                .build();

        // 양방향 관계 설정
        orderBid.assignOrder(order);

        // 플래그 설정 및 저장
        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }

    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof OrderException) {
            throw (OrderException) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new OrderBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }

    @Transactional
    public void matchOrderBid(OrderBid orderBid) {
        try {
            if (orderBid == null) {
                throw new OrderBidNotFoundException("주문 입찰 정보가 없습니다.");
            }

            if (orderBid.getStatus() == BidStatus.MATCHED) {
                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
            }

            orderBid.updateStatus(BidStatus.MATCHED);
        } catch (Exception e) {
            if (e instanceof OrderException) {
                throw e;
            }
            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
            throw new OrderBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

    @Transactional
    public void deleteOrderBid(Long orderBidId) {
        try {
            // OrderBid 조회
            OrderBid orderBid = orderBidRepository.findById(orderBidId)
                    .orElseThrow(() -> new OrderBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));

            // Sale과 연결 여부 확인
            if (orderBid.getSale() != null) {
                throw new OrderBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
            }

            // 매칭 상태 확인
            if (orderBid.getStatus() == BidStatus.MATCHED) {
                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
            }

            // Order와 연결 여부 확인 후 삭제
            if (orderBid.getOrder() != null) {
                orderCommandService.deleteOrder(orderBid.getOrder().getId());
            }

            // OrderBid 삭제
            orderBidRepository.delete(orderBid);
        } catch (Exception e) {
            if (e instanceof OrderException) {
                throw e;
            }
            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new OrderBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
}

package com.fream.back.domain.user.redis;

import com.fream.back.domain.user.entity.Gender;
import com.fream.back.domain.user.entity.Role;
import com.fream.back.domain.user.exception.UserErrorCode;
import com.fream.back.domain.user.exception.UserException;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@Service
public class AuthRedisService {

    // 기본 RedisTemplate (Primary-Replica 자동 분산)
    private final RedisTemplate<String, String> redisTemplate;

    // 쓰기 전용 Primary RedisTemplate
    private final RedisTemplate<String, String> writeRedisTemplate;

    // 읽기 전용 Replica RedisTemplate
    private final RedisTemplate<String, String> readRedisTemplate;

    public AuthRedisService(
            RedisTemplate<String, String> redisTemplate,
            @Qualifier("writeRedisTemplate") RedisTemplate<String, String> writeRedisTemplate,
            @Qualifier("readRedisTemplate") RedisTemplate<String, String> readRedisTemplate) {
        this.redisTemplate = redisTemplate;
        this.writeRedisTemplate = writeRedisTemplate;
        this.readRedisTemplate = readRedisTemplate;
    }

    public void addAccessToken(String accessToken,
                               String email,
                               Integer age,
                               Gender gender,
                               long expirationMillis,
                               String ip,
                               Role role) {

        try {
            String key = "access:" + accessToken;

            // 모든 필드를 하나의 맵으로 구성
            Map<String, String> fields = new HashMap<>();
            fields.put("email", email);
            fields.put("age", String.valueOf(age));
            fields.put("gender", gender.toString());
            fields.put("role", role.toString()); // 권한 정보 추가
            if (ip != null) {
                fields.put("ip", ip);
            }

            // Primary Redis에 쓰기 작업 수행
            writeRedisTemplate.opsForHash().putAll(key, fields);
            writeRedisTemplate.expire(key, Duration.ofMillis(expirationMillis));


        } catch (Exception e) {
            throw new UserException(UserErrorCode.USER_NOT_FOUND, "토큰 저장 중 오류가 발생했습니다.", e);
        }
    }

    public Role getRoleByAccessToken(String accessToken) {

        try {
            Object value = safeReadFromReplica("access:" + accessToken, "role");
            Role role = parseRole(value);

            return role;

        } catch (Exception e) {
            return null;
        }
    }

    public void addRefreshToken(String refreshToken, String email, long expirationMillis) {

        try {
            String key = "refresh:" + refreshToken;

            // Primary Redis에 쓰기 작업 수행
            writeRedisTemplate.opsForHash().put(key, "email", email);
            writeRedisTemplate.expire(key, Duration.ofMillis(expirationMillis));


        } catch (Exception e) {
            throw new UserException(UserErrorCode.USER_NOT_FOUND, "리프레시 토큰 저장 중 오류가 발생했습니다.", e);
        }
    }

    public boolean isAccessTokenValid(String accessToken) {

        try {
            boolean isValid = safeHasKey("access:" + accessToken);

            return isValid;

        } catch (Exception e) {
            return false;
        }
    }

    public boolean isRefreshTokenValid(String refreshToken) {

        try {
            boolean isValid = safeHasKey("refresh:" + refreshToken);

            return isValid;

        } catch (Exception e) {
            return false;
        }
    }

    public String getEmailByAccessToken(String accessToken) {

        try {
            Object value = safeReadFromReplica("access:" + accessToken, "email");
            String email = (value != null) ? value.toString() : null;

            return email;

        } catch (Exception e) {
            return null;
        }
    }

    public Integer getAgeByAccessToken(String accessToken) {

        try {
            Object value = safeReadFromReplica("access:" + accessToken, "age");
            Integer age = parseAge(value);

            return age;

        } catch (Exception e) {
            return null;
        }
    }

    public Gender getGenderByAccessToken(String accessToken) {

        try {
            Object value = safeReadFromReplica("access:" + accessToken, "gender");
            Gender gender = parseGender(value);

            return gender;

        } catch (Exception e) {
            return null;
        }
    }

    public void removeAccessToken(String accessToken) {

        try {
            Boolean deleted = writeRedisTemplate.delete("access:" + accessToken);

        } catch (Exception e) {
            throw new UserException(UserErrorCode.USER_NOT_FOUND, "토큰 삭제 중 오류가 발생했습니다.", e);
        }
    }

    public void removeRefreshToken(String refreshToken) {

        try {
            Boolean deleted = writeRedisTemplate.delete("refresh:" + refreshToken);

        } catch (Exception e) {
            throw new UserException(UserErrorCode.USER_NOT_FOUND, "리프레시 토큰 삭제 중 오류가 발생했습니다.", e);
        }
    }

    // ==================== 내부 헬퍼 메서드 ====================

    private Object safeReadFromReplica(String key, String field) {
        try {
            // 먼저 Replica에서 시도
            Object value = readRedisTemplate.opsForHash().get(key, field);

            if (value == null) {
                // Replica에서 null이면 Primary에서 다시 확인 (replication lag 대응)
                value = writeRedisTemplate.opsForHash().get(key, field);
            }

            return value;

        } catch (Exception replicaException) {
            // Replica 실패 시 Primary로 fallback
            try {
                return writeRedisTemplate.opsForHash().get(key, field);
            } catch (Exception primaryException) {
                return null;
            }
        }
    }

    private boolean safeHasKey(String key) {
        try {
            // 먼저 Replica에서 시도
            boolean exists = readRedisTemplate.hasKey(key);

            if (!exists) {
                // Replica에서 없으면 Primary에서 다시 확인 (replication lag 대응)
                exists = writeRedisTemplate.hasKey(key);
            }

            return exists;

        } catch (Exception replicaException) {
            // Replica 실패 시 Primary로 fallback
            try {
                return writeRedisTemplate.hasKey(key);
            } catch (Exception primaryException) {
                return false;
            }
        }
    }

    // ==================== 파싱 헬퍼 메서드 ====================

    private Role parseRole(Object value) {
        try {
            return (value != null) ? Role.valueOf(value.toString()) : null;
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    private Integer parseAge(Object value) {
        try {
            return (value != null) ? Integer.valueOf(value.toString()) : null;
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private Gender parseGender(Object value) {
        try {
            return (value != null) ? Gender.valueOf(value.toString()) : null;
        } catch (IllegalArgumentException e) {
            return null;
        }
    }
}

