176	public enum SaleStatus {
177	    PENDING_SHIPMENT,    // 판매자 발송 대기
178	    IN_TRANSIT,          // 배송 중
179	    IN_INSPECTION,       // 검수 중
180	    FAILED_INSPECTION,   // 검수 불합격
181	    IN_STORAGE,          // 창고 보관 중
182	    ON_AUCTION,          // 판매 입찰 중
183	    SELLING,             // 판매중 (등록된 상태)
184	    SOLD,                // 판매 완료
185	    AUCTION_EXPIRED;     // 입찰 기한 만료
186	
187	    // 상태 전환 규칙
188	    public boolean canTransitionTo(SaleStatus newStatus) {
189	        return switch (this) {
190	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
191	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
192	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
193	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
194	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
195	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
196	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
197	        };
198	    }
