702	@Override
703	public Page<StyleResponseDto> filterStyles(StyleFilterRequestDto filterRequestDto, Pageable pageable) {
704	    QStyle style = QStyle.style;
705	    QProfile profile = QProfile.profile;
706	    QStyleOrderItem styleOrderItem = QStyleOrderItem.styleOrderItem;
707	    QOrderItem orderItem = QOrderItem.orderItem;
708	    QMediaUrl mediaUrl = QMediaUrl.mediaUrl;
709	    QProductSize productSize = QProductSize.productSize;
710	    QProductColor productColor = QProductColor.productColor;
711	    QProduct product = QProduct.product;
712	    QBrand brand = QBrand.brand;
713	    // 1단계: 필터링 조건에 맞는 스타일 ID 찾기
714	    BooleanBuilder filterBuilder = new BooleanBuilder();
715	    if (filterRequestDto != null) {
716	        if (filterRequestDto.getBrandName() != null) {
717	            filterBuilder.and(brand.name.eq(filterRequestDto.getBrandName()));
718	        }
719	        if (filterRequestDto.getCollectionName() != null) {
720	            filterBuilder.and(product.collection.name.eq(filterRequestDto.getCollectionName()));
721	        }
722	        if (filterRequestDto.getCategoryId() != null) {
723	            filterBuilder.and(product.category.id.eq(filterRequestDto.getCategoryId()));
724	        }
725	        if (filterRequestDto.getProfileName() != null) {
726	            filterBuilder.and(profile.profileName.eq(filterRequestDto.getProfileName()));
727	        }
728	    }
729	    List<Long> filteredStyleIds = queryFactory
730	            .select(style.id)
731	            .from(style)
732	            .leftJoin(style.profile, profile)
733	            .leftJoin(style.styleOrderItems, styleOrderItem)
734	            .leftJoin(styleOrderItem.orderItem, orderItem)
735	            .leftJoin(orderItem.productSize, productSize)
736	            .leftJoin(productSize.productColor, productColor)
737	            .leftJoin(productColor.product, product)
738	            .leftJoin(product.brand, brand)
739	            .where(filterBuilder)
740	            .distinct()
741	            .fetch();
742	    // 2단계: 찾은 ID로 실제 필요한 데이터 조회
743	    var query = queryFactory.select(Projections.constructor(
744	                    StyleResponseDto.class,
745	                    style.id,
746	                    profile.id,
747	                    profile.profileName,
748	                    profile.profileImageUrl,
749	                    style.content,
750	                    // 가장 먼저 저장된 MediaUrl
751	                    JPAExpressions
752	                            .select(mediaUrl.url)
753	                            .from(mediaUrl)
754	                            .where(mediaUrl.style.eq(style)
755	                                    .and(mediaUrl.id.eq(
756	                                            JPAExpressions
757	                                                    .select(mediaUrl.id.min())
758	                                                    .from(mediaUrl)
759	                                                    .where(mediaUrl.style.eq(style))
760	                                    ))),
761	                    style.viewCount,
762	                    style.likes.size() // 좋아요 수 계산
763	            ))
764	            .from(style)
765	            .leftJoin(style.profile, profile)
766	            .where(style.id.in(filteredStyleIds))
767	            .offset(pageable.getOffset())
768	            .limit(pageable.getPageSize());
769	    // 정렬
770	    if (filterRequestDto != null && "popular".equals(filterRequestDto.getSortBy())) {
771	        query.orderBy(style.viewCount.desc(), style.id.desc());
772	    } else {
773	        query.orderBy(style.id.desc());
774	    }
775	    // 데이터 조회
776	    List<StyleResponseDto> content = query.fetch();
777	    // 총 카운트 계산
778	    long total = filteredStyleIds.size();
779	    return PageableExecutionUtils.getPage(content, pageable, () -> total);
780	}
781	    @Override
782	    public StyleDetailResponseDto getStyleDetail(Long styleId) {
783	        QStyle style = QStyle.style;
784	        QProfile profile = QProfile.profile;
785	        QMediaUrl mediaUrl = QMediaUrl.mediaUrl;
786	        QStyleOrderItem styleOrderItem = QStyleOrderItem.styleOrderItem;
787	        QOrderItem orderItem = QOrderItem.orderItem;
788	        QProduct product = QProduct.product;
789	        QProductColor productColor = QProductColor.productColor;
790	        QProductImage productImage = QProductImage.productImage;
791	        QProductSize productSize = QProductSize.productSize;
792	        // 1. 미디어 URL 목록 조회
793	        List<String> mediaUrls = queryFactory
794	                .select(mediaUrl.url)
795	                .from(mediaUrl)
796	                .where(mediaUrl.style.id.eq(styleId))
797	                .orderBy(mediaUrl.id.asc())
798	                .fetch();
799	        List<StyleDetailResponseDto.ProductInfoDto> productInfos = queryFactory
800	                .select(Projections.fields(
801	                        StyleDetailResponseDto.ProductInfoDto.class,
802	                        product.id.as("productId"),
803	                        product.name.as("productName"),
804	                        product.englishName.as("productEnglishName"),
805	                        productColor.colorName.as("colorName"),
806	                        productColor.thumbnailImage.imageUrl.as("thumbnailImageUrl"),
807	                        productSize.salePrice.min().as("minSalePrice")
808	                ))
809	                .from(styleOrderItem)
810	                .leftJoin(styleOrderItem.orderItem, orderItem)
811	                .leftJoin(orderItem.productSize, productSize)
812	                .leftJoin(productSize.productColor, productColor)
813	                .leftJoin(productColor.product, product)
814	                .where(styleOrderItem.style.id.eq(styleId)
815	                        .and(orderItem.isNotNull())
816	                        .and(productSize.isNotNull())
817	                        .and(productColor.isNotNull()))
818	//                .distinct()
819	                .groupBy(product.id, productColor.id)
820	                .fetch();
821	        // 3. 스타일 정보 조회
822	        StyleDetailResponseDto styleDetail = queryFactory
823	                .select(Projections.fields(
824	                        StyleDetailResponseDto.class,
825	                        style.id.as("id"),
826	                        profile.id.as("profileId"),
827	                        profile.profileName.as("profileName"),
828	                        profile.profileImageUrl.as("profileImageUrl"),
829	                        style.content.as("content"),
830	                        ExpressionUtils.as(style.likes.size().longValue(), "likeCount"),
831	                        ExpressionUtils.as(style.comments.size().longValue(), "commentCount"),
832	                        style.createdDate.as("createdDate")
833	                ))
834	                .from(style)
835	                .leftJoin(style.profile, profile)
836	                .where(style.id.eq(styleId))
837	                .fetchOne();
838	        // 4. 미디어 URL과 상품 정보를 DTO에 주입
839	        if (styleDetail != null) {
840	            styleDetail.setMediaUrls(mediaUrls);
841	            styleDetail.setProductInfos(productInfos);
842	        }
843	        return styleDetail;
844	    }
845	    @Override
846	    public Page<ProfileStyleResponseDto> getStylesByProfile(Long profileId, Pageable pageable) {
847	        QStyle style = QStyle.style;
848	        QProfile profile = QProfile.profile;
849	        QMediaUrl mediaUrl = QMediaUrl.mediaUrl;
850	        // 첫 번째 미디어 URL 조회
851	        var query = queryFactory.select(Projections.constructor(
852	                        ProfileStyleResponseDto.class,
853	                        style.id,
854	                        JPAExpressions.select(mediaUrl.url)
855	                                .from(mediaUrl)
856	                                .where(mediaUrl.style.id.eq(style.id)
857	                                        .and(mediaUrl.id.eq(
858	                                                JPAExpressions
859	                                                        .select(mediaUrl.id.min())
860	                                                        .from(mediaUrl)
861	                                                        .where(mediaUrl.style.id.eq(style.id))
862	                                        ))),
863	                        style.likes.size().longValue()  // 좋아요 수
864	                ))
865	                .from(style)
866	                .leftJoin(style.profile, profile)
867	                .where(profile.id.eq(profileId))
868	                .offset(pageable.getOffset())
869	                .limit(pageable.getPageSize());
870	        // 데이터 조회
871	        List<ProfileStyleResponseDto> content = query.fetch();
872	        // 총 카운트 계산
873	        var countQuery = queryFactory.select(style.count())
874	                .from(style)
875	                .leftJoin(style.profile, profile)
876	                .where(profile.id.eq(profileId));
877	        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
