899	                .join(styleOrderItem.orderItem, orderItem)
900	                .join(orderItem.productSize, productSize)
901	                .where(productSize.productColor.id.in(colorIds))
902	                .groupBy(productSize.productColor.id)
903	                .fetch();
904	        // 결과 -> Map<colorId, styleCount>
905	        return results.stream()
906	                .collect(Collectors.toMap(
907	                        t -> t.get(productSize.productColor.id),
908	                        t -> t.get(styleOrderItem.style.id.countDistinct())
909	                ));
