                log.debug("Nginx 캐시 퍼지 성공");
            } catch (Exception e) {
                log.warn("Nginx 캐시 퍼지 실패: {}", e.getMessage());
                // 캐시 퍼지 실패는 전체 프로세스를 중단하지 않음
            }
            log.info("스타일 삭제 완료: styleId={}", styleId);
            return ResponseEntity.ok().build();
        } catch (StyleException e) {
            // StyleException은 이미 로깅됨
