99	public enum ShipmentStatus {
100	    PENDING {
101	        @Override
102	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
103	            return nextStatus == SHIPPED || nextStatus == CANCELED;
104	        }
105	    },
106	    SHIPPED {
107	        @Override
108	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
109	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
110	        }
111	    },
112	    IN_TRANSIT {
113	        @Override
114	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
115	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
116	                    || nextStatus == DELIVERED;
117	        }
118	    },
119	    OUT_FOR_DELIVERY {
120	        @Override
121	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
122	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
123	        }
124	    },
125	    DELIVERED {
126	        @Override
127	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
128	            return false; // 배송 완료 이후로는 상태 전환 없음
129	        }
130	    },
131	    RETURNED {
132	        @Override
133	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
134	            return nextStatus == CANCELED;
135	        }
136	    },
137	    CANCELED {
138	        @Override
139	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
140	            return false; // 취소 이후 상태 전환 없음
141	        }
142	    },
143	    DELAYED {
144	        @Override
145	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
146	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
147	        }
148	    },
149	    FAILED_DELIVERY {
150	        @Override
151	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
152	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
153	        }
154	    };
155	
156	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
