                log.debug("Chromium 브라우저 시작 (headless={}, slowMo={}ms)",
                        LAUNCH_OPTIONS.headless, LAUNCH_OPTIONS.slowMo);
                browser = playwright.chromium().launch(LAUNCH_OPTIONS);
