                    dto.setHashtags(styleToHashtagsMap.getOrDefault(dto.getId(), Collections.emptyList()));
                }
            }
            return styles;
        } catch (Exception e) {
            throw new StyleException(StyleErrorCode.STYLE_INVALID_REQUEST,
