    private void handleRefundIfNecessary(Payment payment) {
        Instant start = Instant.now();
        try {
            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                log.warn("환불 처리 불가: 결제ID={}, 결제식별자(impUid)가 없습니다.", payment.getId());
                return;
            }


            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(PaymentStatus.REFUNDED);
                paymentRepository.save(payment);
            } else {
                log.error("결제 환불 처리 실패: 결제ID={}", payment.getId());
                throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 요청이 실패했습니다. 관리자에게 문의하세요.");
            }

            // 처리 시간 로깅
            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
        } catch (PaymentException e) {
            throw e; // 이미 PaymentException이면 그대로 전파
        } catch (Exception e) {
            log.error("결제 환불 처리 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment.getId(), e.getMessage(), e);
            throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
                    "환불 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }

    private void notifyUsersAndUpdateSaleStatus(Order order, Payment payment) {
        try {

            // 1. OrderBid 조회
            OrderBid orderBid = order.getOrderBid();
            if (orderBid == null) {
                // OrderBid가 없으면 SaleBid 탐색
                SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
                if (saleBid == null) {
                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
                    return;
                }

                Sale sale = saleBid.getSale();
                if (sale == null) {
                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
                    return;
                }

                sendNotifications(order, sale); // 알림 전송
                sale.updateStatus(SaleStatus.SOLD); // Sale 상태 변경
                return;
            }

            // 2. Sale 조회
            Sale sale = orderBid.getSale();
            if (sale == null) {
                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
                return;
            }

            sendNotifications(order, sale); // 알림 전송

            // 3. Sale 상태 변경
            sale.updateStatus(SaleStatus.SOLD);
        } catch (Exception e) {
            // 알림 및 상태 업데이트 실패 로깅만 하고 예외는 발생시키지 않음 (핵심 기능이 아니므로)
            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
        }
    }

    private void sendNotifications(Order order, Sale sale) {
        try {
            User buyer = order.getUser();
            if (buyer != null) {
                notificationCommandService.createNotification(
                        buyer.getId(),
                        NotificationCategory.SHOPPING,
                        NotificationType.BID,
                        "결제가 완료되었습니다. 주문 ID: " + order.getId()
                );
            }

            User seller = sale.getSeller();
            if (seller != null) {
                notificationCommandService.createNotification(
                        seller.getId(),
                        NotificationCategory.SHOPPING,
                        NotificationType.BID,
                        "구매자가 결제를 완료하였습니다. 판매 ID: " + sale.getId()
                );
            }
        } catch (Exception e) {
            // 알림 전송 실패 로깅만 하고 예외는 발생시키지 않음
            log.warn("결제 완료 알림 전송 중 오류 발생: 주문ID={}, 판매ID={}, 오류={}",
                    order.getId(), sale.getId(), e.getMessage());
        }
    }

    private void validateBank(String bankName) {
        try {
            if (bankName == null || bankName.isBlank()) {
                throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO, "은행 이름은 필수입니다.");
            }

            try {
                Bank.valueOf(bankName.toUpperCase());
            } catch (IllegalArgumentException e) {
                throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO,
                        "지원하지 않는 은행입니다: " + bankName);
            }
        } catch (PaymentException e) {
            throw e; // 이미 PaymentException이면 그대로 전파
        } catch (Exception e) {
            throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO,
                    "은행 정보 검증 중 오류가 발생했습니다.", e);
        }
    }

    @Transactional
    public void updatePaymentStatus(Payment payment, PaymentStatus newStatus) {
        Instant start = Instant.now();
        try {
            if (payment == null) {
                throw new PaymentNotFoundException("결제 정보가 없습니다.");
            }

            if (!payment.getStatus().canTransitionTo(newStatus)) {
                throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_STATUS,
                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
            }

                    payment.getId(), payment.getStatus(), newStatus);

            payment.updateStatus(newStatus);
            paymentRepository.save(payment);


            // 처리 시간 로깅
            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
        } catch (PaymentException e) {
            log.error("결제 상태 변경 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    payment != null ? payment.getId() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e; // 이미 PaymentException이면 그대로 전파
        } catch (Exception e) {
            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment != null ? payment.getId() : "null", e.getMessage(), e);
            throw new PaymentException(PaymentErrorCode.PAYMENT_UPDATE_FAILED,
                    "결제 상태 변경 중 오류가 발생했습니다.", e);
        }
    }

    @Transactional
    public String refundPayment(Long paymentId) {
        Instant start = Instant.now();
        try {

            // 1. Payment 정보 조회
            Payment payment = paymentRepository.findById(paymentId)
                    .orElseThrow(() -> new PaymentNotFoundException("결제 ID: " + paymentId + "를 찾을 수 없습니다."));

            // 2. 현재 상태 확인
            if (!payment.getStatus().canTransitionTo(PaymentStatus.REFUND_REQUESTED)) {
                throw new PaymentException(PaymentErrorCode.INVALID_PAYMENT_STATUS,
                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
            }

            // 3. 포트원 API를 통해 환불 요청
            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 가능한 결제 ID가 없습니다.");
            }

            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(PaymentStatus.REFUNDED); // 상태를 REFUNDED로 변경
                paymentRepository.save(payment);

                // 환불 성공 시 알림 발송
                sendRefundNotification(payment);

                // 처리 시간 로깅
                Instant end = Instant.now();
                Duration duration = Duration.between(start, end);

                return "환불이 성공적으로 완료되었습니다.";
            } else {
                payment.updateStatus(PaymentStatus.REFUND_REQUESTED); // 환불 요청 상태로 업데이트
                paymentRepository.save(payment);
                log.warn("결제 환불 요청 실패: 결제ID={}, 상태=REFUND_REQUESTED", paymentId);
                return "환불 요청이 실패하였습니다. 관리자에게 문의하세요.";
            }
        } catch (PaymentException e) {
            log.error("결제 환불 요청 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    paymentId, e.getErrorCode().getCode(), e.getMessage());
            throw e; // 이미 PaymentException이면 그대로 전파
        } catch (Exception e) {
            log.error("결제 환불 요청 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    paymentId, e.getMessage(), e);
            throw new PaymentException(PaymentErrorCode.PAYMENT_CANCELLATION_FAILED,
                    "환불 요청 중 오류가 발생했습니다: " + e.getMessage());
        }
    }

    private void sendRefundNotification(Payment payment) {
        try {
            User user = payment.getUser();
            if (user == null) {
                log.warn("환불 알림 발송 실패: 결제ID={}, 사용자 정보가 없습니다.", payment.getId());
                return;
            }

            Order order = payment.getOrder();
            String orderInfo = order != null ? "주문 ID: " + order.getId() : "환불금액: " + payment.getPaidAmount() + "원";

            notificationCommandService.createNotification(
                    user.getId(),
                    NotificationCategory.SHOPPING,
                    NotificationType.REFUND,
                    "결제가 환불되었습니다. " + orderInfo
            );

            // 판매자 알림 - 주문과 연결된 판매 정보가 있는 경우
            if (order != null) {
                Sale sale = null;

                // OrderBid를 통한 Sale 조회
                OrderBid orderBid = order.getOrderBid();
                if (orderBid != null) {
                    sale = orderBid.getSale();
                }
                // SaleBid를 통한 Sale 조회
                else {
                    SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
                    if (saleBid != null) {
                        sale = saleBid.getSale();
                    }
                }

                if (sale != null && sale.getSeller() != null) {
                    User seller = sale.getSeller();
                    notificationCommandService.createNotification(
                            seller.getId(),
                            NotificationCategory.SHOPPING,
                            NotificationType.REFUND,
                            "구매자의 결제가 환불되었습니다. 판매 ID: " + sale.getId()
                    );
                            seller.getId(), sale.getId());

                    // 중고거래 특성상 판매 완료 후에는 상태를 변경하지 않음
                    // 판매자가 직접 새로운 판매 게시글을 등록해야 함
                }
            }
        } catch (Exception e) {
            // 알림 전송 실패 로깅만 하고 예외는 발생시키지 않음
            log.warn("환불 알림 전송 중 오류 발생: 결제ID={}, 오류={}",
                    payment.getId(), e.getMessage());
        }
    }
}

package com.fream.back.domain.user.service.command;
@Slf4j
@Service
@RequiredArgsConstructor
public class UserCommandService {
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final ProfileCommandService profileService;
    private final FileUtils fileUtils;
    private final NotificationCommandService notificationCommandService;
    private final IdentityVerificationService identityVerificationService;
    /**
     * 본인인증을 통한 회원가입 처리
     * @param dto 회원가입 정보
     * @return 생성된 사용자 정보
     */
    @Transactional
    public User registerUser(UserRegistrationDto dto) {
        try {
            if (!dto.getIsOver14() || !dto.getTermsAgreement() || !dto.getPrivacyAgreement()) {
                        dto.getEmail(), dto.getIsOver14(), dto.getTermsAgreement(), dto.getPrivacyAgreement());
                throw new UserException(UserErrorCode.INVALID_VERIFICATION_CODE, "필수 동의 조건을 만족하지 않았습니다.");
            }
            if (userRepository.existsByEmail(dto.getEmail())) {
                throw new DuplicateEmailException(dto.getEmail());
            }
            if (dto.getIdentityVerificationId() == null || dto.getIdentityVerificationId().isEmpty()) {
                throw new IdentityVerificationFailedException();
            }
            VerifiedCustomerDto verifiedCustomer;
            try {
                verifiedCustomer = identityVerificationService.verifyIdentity(dto.getIdentityVerificationId());
            } catch (Exception e) {
                throw new IdentityVerificationFailedException(dto.getIdentityVerificationId(), "본인인증 검증에 실패했습니다.");
            }
            if (verifiedCustomer.getCi() != null && !verifiedCustomer.getCi().isEmpty()) {
                userRepository.findByCi(verifiedCustomer.getCi())
                        .ifPresent(existingUser -> {
                            throw new DuplicateEmailException(existingUser.getEmail(), "이미 가입된 사용자입니다. 다른 계정으로 로그인해주세요.");
                        });
            }
            if (dto.getIsOver14()) {
                validateAge(verifiedCustomer.getBirthDate());
            }
            User referrer = null;
            if (dto.getReferralCode() != null && !dto.getReferralCode().isEmpty()) {
                referrer = userRepository.findByReferralCode(dto.getReferralCode())
                        .orElseThrow(() -> {
                            return new UserException(UserErrorCode.USER_NOT_FOUND, "유효하지 않은 추천인 코드입니다.");
                        });
            }
            Gender gender = convertToGender(verifiedCustomer.getGender());
            Integer age = calculateAge(verifiedCustomer.getBirthDate());
            String encodedPassword = passwordEncoder.encode(dto.getPassword());
            User user = User.builder()
                    .email(dto.getEmail())
                    .password(encodedPassword)
                    .referralCode(generateUniqueReferralCode())
                    .shoeSize(dto.getShoeSize())
                    .phoneNumber(verifiedCustomer.getPhoneNumber()) // 본인인증으로 검증된 전화번호 사용
                    .age(age) // 계산된 나이 저장
                    .gender(gender) // 본인인증으로 검증된 성별 정보
                    .termsAgreement(dto.getTermsAgreement())
                    .phoneNotificationConsent(dto.getAdConsent() != null ? dto.getAdConsent() : false)
                    .emailNotificationConsent(dto.getOptionalPrivacyAgreement() != null ? dto.getOptionalPrivacyAgreement() : false)
                    .optionalPrivacyAgreement(dto.getOptionalPrivacyAgreement() != null ? dto.getOptionalPrivacyAgreement() : false)
                    .isVerified(true) // 본인인증 완료 상태 설정
                    .ci(verifiedCustomer.getCi()) // CI 저장
                    .di(verifiedCustomer.getDi()) // DI 저장
                    .referrer(referrer)
                    .build();
            user.updateConsent(dto.getAdConsent(), dto.getOptionalPrivacyAgreement());
            if (referrer != null) {
                user.addReferrer(referrer);
            }
            userRepository.save(user);
            try {
                profileService.createDefaultProfile(user);
            } catch (Exception e) {
                throw new ProfileNotFoundException("기본 프로필 생성에 실패했습니다.");
            }
                    user.getEmail(), user.getPhoneNumber(), user.isVerified());
            return user;
        } catch (UserException e) {
            throw e;
        } catch (Exception e) {
            throw new UserException(UserErrorCode.USER_NOT_FOUND, "회원가입 처리 중 오류가 발생했습니다.", e);
        }
    }
    @Transactional
    public void deleteAccount(String email) {
        try {
            User user = userRepository.findByEmail(email)
                    .orElseThrow(() -> {
                        return new UserNotFoundException(email);
                    });
            try {
                notificationCommandService.deleteNotificationsByUser(email);
            } catch (Exception e) {
            }
            try {
                if (user.getProfile() != null && user.getProfile().getProfileImageUrl() != null) {
                    fileUtils.deleteFile("profile_images", user.getProfile().getProfileImageUrl());
                }
            } catch (Exception e) {
            }
            userRepository.delete(user);
        } catch (UserException e) {
            throw e;
        } catch (Exception e) {
            throw new UserException(UserErrorCode.USER_NOT_FOUND, "계정 삭제 처리 중 오류가 발생했습니다.", e);
        }
    }
    /**
     * 생년월일로 만 14세 이상인지 검증
     */
    private void validateAge(String birthDate) {
        try {
            LocalDate birth = LocalDate.parse(birthDate, DateTimeFormatter.ISO_DATE);
            LocalDate minAgeDate = LocalDate.now().minusYears(14);
            if (birth.isAfter(minAgeDate)) {
                throw new UserException(UserErrorCode.INVALID_VERIFICATION_CODE, "만 14세 이상만 가입 가능합니다.");
            }
        } catch (DateTimeParseException e) {
            throw new UserException(UserErrorCode.INVALID_VERIFICATION_CODE, "올바르지 않은 생년월일 형식입니다.");
        }
    }
    /**
     * 생년월일로 나이 계산
     */
    private Integer calculateAge(String birthDate) {
        try {
            LocalDate birth = LocalDate.parse(birthDate, DateTimeFormatter.ISO_DATE);
            return Period.between(birth, LocalDate.now()).getYears();
        } catch (DateTimeParseException e) {
            return null;
        }
    }
    /**
     * 본인인증 성별 정보 변환
     */
    private Gender convertToGender(String genderStr) {
        if (genderStr == null || genderStr.isEmpty()) {
            return null;
        }
        if ("male".equalsIgnoreCase(genderStr) || "M".equalsIgnoreCase(genderStr)) {
            return Gender.MALE;
        } else if ("female".equalsIgnoreCase(genderStr) || "F".equalsIgnoreCase(genderStr)) {
            return Gender.FEMALE;
        }
        return null;
    }
    private String generateUniqueReferralCode() {
        String referralCode;
        int attempts = 0;
        final int maxAttempts = 10;
        do {
            referralCode = UUID.randomUUID().toString().substring(0, 8).toUpperCase();
            attempts++;
            if (attempts >= maxAttempts) {
                throw new UserException(UserErrorCode.USER_NOT_FOUND, "추천인 코드 생성에 실패했습니다.");
            }
        } while (userRepository.findByReferralCode(referralCode).isPresent()); // 중복 체크
        return referralCode;
    }
