        @Valid @ModelAttribute FAQUpdateRequestDto requestDto
) {
    if (id == null) {
        throw new FAQNotFoundException("수정할 FAQ ID가 필요합니다.");
    }

    // 인증 정보 추출
    String email = extractEmailFromSecurityContext();

    // 관리자 권한 확인
