                originalFilename = "unknown";
            }
            String extension = "";
            int dotIndex = originalFilename.lastIndexOf(".");
            if (dotIndex != -1) {
                extension = originalFilename.substring(dotIndex);  // ".jpg", ".png" 등
            }
            // 3) 고유 파일명 생성
