            file.transferTo(filePath.toFile());
            // 반환: DB 등에 저장될 "uniqueFilename" (ex: "thumbnail_abc123.jpg")
            return uniqueFilename;
        } catch (UnsupportedFileTypeException | DirectoryCreationException e) {
            // 이미 로깅 처리됨
